#!/usr/bin/env python3
"""Regression: collected asset directories and required fonts are packaged fail-closed."""

from __future__ import annotations

import json
from pathlib import Path
import subprocess
import sys
import tempfile


def run(script: Path, *args: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [sys.executable, str(script), *args], text=True, capture_output=True
    )


def main() -> int:
    script = Path(__file__).resolve().parent / "prepare_assembly_packaging.py"
    guard = Path(__file__).resolve().parent / "assembly_tdd_guard.py"
    with tempfile.TemporaryDirectory(prefix="iff-assembly-packaging-") as raw_tmp:
        project = Path(raw_tmp) / "project"
        feature = project / "lanhu" / "specs" / "home"
        (feature / "board-a").mkdir(parents=True)
        (feature / "board-b").mkdir()
        presentation = project / "lib" / "home" / "presentation"
        presentation.mkdir(parents=True)
        (project / "assets" / "images").mkdir(parents=True)
        (project / "assets" / "feature").mkdir(parents=True)
        (project / "assets" / "images" / "a.png").write_bytes(b"a")
        (project / "assets" / "feature" / "b.png").write_bytes(b"b")
        (presentation / "board_a_canvas.dart").write_text(
            "// GENERATED by iFF generate_canvas.py\n"
            "Image.asset('assets/images/a.png');\n"
            "const TextStyle(fontFamily: 'SF Pro Text');\n",
            encoding="utf-8",
        )
        (presentation / "board_b_canvas.dart").write_text(
            "// GENERATED by iFF generate_canvas.py\n"
            "Image.asset(\"assets/feature/b.png\");\n",
            encoding="utf-8",
        )
        pubspec = project / "pubspec.yaml"
        pubspec.write_text(
            "name: packaging_fixture\nflutter:\n  uses-material-design: true\n",
            encoding="utf-8",
        )
        font_source = project / "fixture-SFNS.ttf"
        font_source.write_bytes(b"synthetic-font")
        evidence = feature / "assembly_packaging.json"
        test_target = project / "test" / "home"
        test_target.mkdir(parents=True)
        (test_target / "home_test.dart").write_text("void main() {}\n", encoding="utf-8")
        fake_flutter = project / "fake_flutter.py"
        fake_flutter.write_text(
            "#!/usr/bin/env python3\nimport sys\nprint('expected red')\nraise SystemExit(1)\n",
            encoding="utf-8",
        )
        fake_flutter.chmod(0o755)
        guarded_red = run(
            guard,
            "red",
            "--spec-root",
            str(feature),
            "--project-root",
            str(project),
            "--test-target",
            "test/home",
            "--failure-kind",
            "missing_feature_behavior",
            "--flutter",
            str(fake_flutter),
        )
        assert guarded_red.returncode == 0, guarded_red.stdout + guarded_red.stderr

        prepared = run(
            script,
            "prepare",
            "--spec-root",
            str(feature),
            "--project-root",
            str(project),
            "--pubspec",
            str(pubspec),
            "--font-source",
            str(font_source),
            "--out",
            str(evidence),
        )
        assert prepared.returncode == 0, prepared.stdout + prepared.stderr
        pubspec_text = pubspec.read_text(encoding="utf-8")
        assert "    - assets/feature/" in pubspec_text
        assert "    - assets/images/" in pubspec_text
        assert "    - family: SF Pro Text" in pubspec_text
        assert "        - asset: fonts/SFProText.ttf" in pubspec_text
        assert (project / "fonts" / "SFProText.ttf").read_bytes() == b"synthetic-font"

        manifest = json.loads(evidence.read_text(encoding="utf-8"))
        assert manifest["phase"] == "post_red_pre_green"
        assert manifest["redEvidence"]["failureKind"] == "missing_feature_behavior"
        assert manifest["assetDirectories"] == ["assets/feature/", "assets/images/"]
        assert manifest["fonts"] == [
            {"asset": "fonts/SFProText.ttf", "family": "SF Pro Text"}
        ]
        verified = run(script, "verify", "--evidence", str(evidence))
        assert verified.returncode == 0, verified.stdout + verified.stderr

        interaction_evidence = feature / "interaction_test_evidence.json"
        direct_green = json.loads(interaction_evidence.read_text(encoding="utf-8"))
        direct_green["green"] = {"exit_code": 0}
        interaction_evidence.write_text(json.dumps(direct_green), encoding="utf-8")
        backfill = run(
            script,
            "prepare",
            "--spec-root",
            str(feature),
            "--project-root",
            str(project),
            "--pubspec",
            str(pubspec),
            "--font-source",
            str(font_source),
            "--out",
            str(feature / "late_packaging.json"),
        )
        assert backfill.returncode != 0
        assert "cannot be backfilled" in (backfill.stdout + backfill.stderr)

        pubspec.write_text(
            pubspec_text.replace("    - assets/feature/\n", ""), encoding="utf-8"
        )
        rejected = run(script, "verify", "--evidence", str(evidence))
        assert rejected.returncode != 0
        assert "asset directory not registered" in (rejected.stdout + rejected.stderr)

    print("PASS: assembly packaging registers every asset directory and required font fail-closed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
